from typing import Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class ProfileMethods(BaseClient):
    """
    Методы группы 'Профиль' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=84)
    @tracer.start_as_current_span("profile.rapi_profile_update")
    def rapi_profile_update(
        self,
        first_name: str,
        last_name: str,
        middle_name: Optional[str] = None,
        about: Optional[str] = None,
    ):
        """
        Изменить информацию о профиле

        Дает возможность поменять поля профиля пользователя,
        список разрешенных для изменения полей задается на сервере.
        :param  first_name: Новое имя
        :param  last_name: Новая фамилия
        :param  middle_name: Новое отчество
        :param  about: Новая информация о себе
        """
        return self.post(
            "rapi/profile/update",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "firstName": first_name,
                    "lastName": last_name,
                    "middleName": middle_name,
                    "about": about,
                },
            },
        )
